/*
  вэрн.be4d00a6.js — ПЕРЕКЛЮЧАТЕЛЬ. Один адрес, три части, без перезагрузки.

  Чем отличается от соседей: герой.js знает только про сборку, ход.js
  и карта.js — только про мир. Про то, что они живут на одном адресе,
  знает один этот файл. Больше нигде связи между частями нет.

  Порядок такой:
      герой уже есть  →  сразу мир, ворота пропускаются
      героя нет       →  ворота  →  сборка  →  мир

  Видимого текста и настроечных чисел здесь нет, как и в остальной
  логике: надписи стоят метками data-т в разметке.
*/

'use strict';

(function () {

const $ = (ид) => document.getElementById(ид);

/* Домов ровно два, показан всегда один. Внутри дома своё
   переключение экранов, и оно нас не касается. */
const ДОМА = ['дом-сборки', 'дом-мира'];

function показатьДом(ид) {
  ДОМА.forEach((д) => { $(д).hidden = (д !== ид); });
  window.scrollTo(0, 0);
}

/* ── три части адреса ─────────────────────────────────────────────── */

function вСборку() {
  показатьДом('дом-сборки');
  СБОРКА.показать();
}

function воВорота() {
  показатьДом('дом-мира');
  ХОД.воВорота();
}

/*  В мир. Запись героя перечитывается каждый раз: он мог только что
    смениться в сборке, а перезагрузки, которая обновляла бы всё сама,
    больше нет.                                                      */
function вМир() {
  ХОД.перечитатьГероя();
  показатьДом('дом-мира');
  ХОД.вКарту();
}

/* ── запуск ───────────────────────────────────────────────────────── */

function запуск() {
  СБОРКА.запуск();
  ХОД.запуск();

  /*  Герой подтверждён — человек оказывается в мире сразу, не ожидая
      портрета. Портрет догоняет и ложится в карточку. Это условие
      приёмки: мир открывается, даже если портрета нет вовсе.       */
  СБОРКА.когдаГотов(вМир);

  /* из ворот — в сборку; кнопка там одна, и значит она только это */
  $('к-войти').addEventListener('click', вСборку);

  /* из мира — в карточку героя; там же «получить портрет» и «заново» */
  $('к-переделать').addEventListener('click', вСборку);
  $('плашка-героя').addEventListener('click', вСборку);

  /* из карточки — обратно в мир */
  $('к-в-мир').addEventListener('click', вМир);

  /*  Поломка чтения записи — не то же, что «героя нет». Ворота
      сказали бы человеку, что он здесь впервые, а его герой цел и
      лежит в памяти браузера. Поэтому разговор о поломке идёт в доме
      сборки, где для него собран экран.                            */
  if (СБОРКА.поломка()) вСборку();
  else if (СБОРКА.есть()) вМир();
  else воВорота();
}

document.addEventListener('DOMContentLoaded', запуск);

})();
